// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is injectable time source.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token bucket.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// New validates arguments and returns a full bucket.
func New(capacity int, ratePerSecond float64, clock Clock) (*TokenBucket, error) {
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if ratePerSecond <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &TokenBucket{
		capacity: float64(capacity),
		tokens:   float64(capacity),
		rate:     ratePerSecond,
		last:     now,
		clock:    clock,
	}, nil
}

// AllowN consumes n tokens if available.
func (b *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refill()
	if b.tokens >= float64(n) {
		b.tokens -= float64(n)
		return true
	}
	return false
}

// Allow consumes one token if available.
func (b *TokenBucket) Allow() bool { return b.AllowN(1) }

// Tokens returns the current available token count.
func (b *TokenBucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refill()
	return b.tokens
}

func (b *TokenBucket) refill() {
	now := b.clock.Now()
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
}
